import XCTest
final class ProbeTests:XCTestCase {
func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);var n=0;while !q.allElementsBoundByIndex.contains(where:{$0.isHittable}) && n<10{let e=q.firstMatch;let scroll=app.scrollViews.firstMatch;let up=e.frame.midY>=scroll.frame.minY+35;let from=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.72:0.35));let to=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.48:0.59));from.press(forDuration:0.1,thenDragTo:to);n+=1};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name+app.debugDescription);return};b.tap()}
func type(_ f:XCUIElement,_ value:String){f.tap();XCTAssertTrue(XCUIApplication(bundleIdentifier:"com.example.fancy.dev").keyboards.firstMatch.waitForExistence(timeout:10));for c in value{f.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
func option(_ app:XCUIApplication,_ name:String){let q=app.otherElements.matching(NSPredicate(format:"label == %@",name));XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);let e=q.firstMatch;var n=0;while !e.isHittable && n<8{let scroll=app.scrollViews.firstMatch;let up=e.frame.midY>=scroll.frame.minY+35;let from=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.72:0.35));let to=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.48:0.59));from.press(forDuration:0.1,thenDragTo:to);n+=1};XCTAssertTrue(e.isHittable,app.debugDescription);e.tap()}
func shot(_ app:XCUIApplication,_ name:String){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
func selected(_ app:XCUIApplication,_ name:String)->Bool{return app.otherElements.matching(NSPredicate(format:"label == %@",name)).allElementsBoundByIndex.contains(where:{$0.isSelected || (($0.value as? String) ?? "").hasSuffix(", checked")})}
func openSurvey(_ app:XCUIApplication){tap(app,"Profile, tab, 5 of 5");XCTAssertTrue(app.staticTexts["QA Final Bystander"].firstMatch.waitForExistence(timeout:12),app.debugDescription);tap(app,"Settings");tap(app,"Product survey");XCTAssertTrue(app.buttons["Update survey"].waitForExistence(timeout:12),app.debugDescription)}
func testNativeJ011Report201(){continueAfterFailure=false;let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();tap(app,"Profile, tab, 5 of 5");XCTAssertTrue(app.staticTexts["QA Final Host"].firstMatch.waitForExistence(timeout:12),app.debugDescription);tap(app,"Meals, tab, 2 of 5");option(app,"Past");let label="A relaxed meal together, Fri 23 Oct · 00:00 BST, 2 of 2 confirmed";let q=app.buttons.matching(NSPredicate(format:"label == %@",label));XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);var found=false;for index in 0..<q.count{app.buttons.matching(NSPredicate(format:"label == %@",label)).element(boundBy:index).tap();if app.buttons["After the meal"].waitForExistence(timeout:3){found=true;break};tap(app,"Back")};XCTAssertTrue(found,app.debugDescription);tap(app,"Report this meal");XCTAssertTrue(app.staticTexts["Report a concern"].firstMatch.waitForExistence(timeout:12),app.debugDescription);let f=app.textViews.matching(identifier:"What happened?").firstMatch;XCTAssertTrue(f.exists,app.debugDescription);f.tap();f.typeText("Synthetic QA attendance dispute for the J011 support correction workflow.");tap(app,"Send report");XCTAssertTrue(app.staticTexts["Report received"].firstMatch.waitForExistence(timeout:12),app.debugDescription);shot(app,"codex-j011-report-received");print("QA_CODEX_J011_REPORT_PASS\n"+app.debugDescription)}
}
